"""Report verified traffic inputs and explicit gaps; no demand or capacity fitting."""
from pathlib import Path
import json,csv,hashlib,html,os
ROOT=Path(__file__).resolve().parents[2];P=ROOT/'data/processed/three_ward_traffic_data_search_v1';R=ROOT/'data/exp/feasibility-check/three_ward_traffic_data_search_v1'
def main():
 s=json.loads((R/'summary.json').read_text());checks={'3downloaded_sources_bound':all(hashlib.sha256((ROOT/f['path']).read_bytes()).hexdigest()==f['sha256']for f in s['downloaded_sources']),'391core_sections':sum(s['three_ward_section_rows_by_code'].values())==s['three_ward_section_rows']==391,'159source_columns_preserved':len(next(csv.reader((P/'three_ward_census_sections.csv').open(encoding='utf-8-sig'))))==159,'capacity_not_claimed_as_direct_field':not s['direct_capacity_column_present'],'PTcatalog_not_claimed_as_obtained_file':'not obtained'in s['pt_catalog']['status'],'no_simulated_people_or_traffic':'No traffic assignment'in s['not_done']and'No affected-person counts'in s['not_done']};assert all(checks.values()),checks
 (R/'validation.json').write_text(json.dumps(dict(all_passed=True,checks=checks),indent=2)+'\n')
 sources=[('人从哪里到哪里','2018东京PT：区域目的与主要交通方式OD；区域时段发到量和时刻别滞留人口','官方目录已确认，尚未取得文件。公开基础表与需注册的自定义集计分开；人次不直接等于车次。','https://www.tokyo-pt.jp/data/H30'),('有多少车、正常速度','2021道路交通普查：交通量、方向、车型、混杂度、旅行速度','已取得基本表与小时表。东京3335条普查分段中三区391条：千代田117、中央102、港172。部分是推估值，不是391个实测站点，也不覆盖全部支路。','https://www.mlit.go.jp/road/census/r3/index.html'),('时段交通量','东京都2021区部24小时交通量CSV','已取得558行含多行表头的文件，尚未映射到当前路网；不是实时交通。','https://www.kensetsu.metro.tokyo.lg.jp/road/information/3sensasu'),('道路容量','车道、宽度、信号、速度等字段及官方容量方法','CSV没有直接容量列。官方混杂度为12小时交通量／12小时容量，可作估计约束；不能直接当作每小时交叉口容量或暴雨容量。','https://www.mlit.go.jp/road/census/r3/data/pdf/kasyorep.pdf'),('通勤通学人数','2020人口普查：常住地、工作／学习地及通常交通方式','目录已确认，未新增下载；可约束人口与通勤，不代表全部目的出行或特定时刻在场人口。','https://www.e-stat.go.jp/stat-search/database?layout=datalist&toukei=00200521&tstat=000001136464&tclass1=000001136469')]
 body='<h1>交通需求与道路容量：数据可用性</h1><p><b>有调查统计可以约束基线，剩余部分再设情景。</b>本次只查找和检查来源，未运行交通分配、容量拟合、拥堵或人数计算；原8组实验不变。</p><table><tr>'+''.join('<th>'+x+'</th>'for x in ['问题','数据','本轮核验与边界'])+'</tr>'
 for a,b,c,u in sources:body+='<tr><td>'+a+'</td><td><a href="'+html.escape(u,quote=True)+'">'+b+'</a></td><td>'+c+'</td></tr>'
 body+='</table><h2>缺口与假设的位置</h2><ul><li>用区域OD约束方向和总量，用交通普查约束干道流量、时段与速度。汽车人次和驾驶者车次要分别处理。</li><li>区域内部的起终点位置、未观测支路容量、从日OD到时段联合OD的分配属于待声明的模型假设。</li><li>暴雨下取消出行、改变出发时间、改道、轨道转汽车以及容量随积水的变化另设情景；具体数值尚未选定。</li><li>不同档位下比较相同需求与其他条件的无措施／措施结果；不用假定人数或无限容量替代缺测。</li></ul><p>数据年份2018／2020／2021与2024／2025雨场及现代路网不同，需单列，不能称为历史暴雨当天真实交通。</p><h2>获取状态</h2><p>三份交通量CSV已保存。PT官方目录与注册规则已核实；直接文件请求在本环境遇到证书链验证错误，因此PT文件尚未取得。未绕过验证、未注册账号，不将访问失败解释为没有数据。</p><h2>本地文件</h2><ul>'
 for f in [R/'summary.json',R/'validation.json',P/'three_ward_census_sections.csv',P/'census_field_inventory.json',P/'sources/acquisition_manifest.json']+[ROOT/f['path']for f in s['downloaded_sources']]:body+='<li><a href="'+os.path.relpath(f,R)+'">'+f.name+'</a></li>'
 body+='</ul><p>研究决定：MILI-D-20261017-013。</p>'
 (R/'review.html').write_text('<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>交通需求与容量数据</title><style>body{font:16px/1.8 system-ui;max-width:1200px;margin:auto;padding:28px;background:#f4f7f8;color:#263e4b}table{border-collapse:collapse;background:white;width:100%;font-size:14px}td,th{padding:10px;border:1px solid #cddae2;text-align:left}a{color:#17648c}h2{margin-top:30px}</style>'+body+'</html>')
 files=[R/'summary.json',R/'validation.json',R/'review.html',P/'three_ward_census_sections.csv',P/'census_field_inventory.json',P/'sources/acquisition_manifest.json',ROOT/'src/preprocessing/inspect_tokyo_traffic_data_sources_v1.py',Path(__file__)]
 (R/'delivery_manifest.json').write_text(json.dumps(dict(files={str(f.relative_to(ROOT)):hashlib.sha256(f.read_bytes()).hexdigest()for f in files},new_traffic_assignment=False,people_counted=False),indent=2)+'\n');print('Verified source review saved;6checks passed;3downloadedCSVtables.')
if __name__=='__main__':main()
